int partition(int a[],int low,int high)
{
    int l=low,r=high,pivot=a[low];
    while(l<=high&&r>=low)
    {
        while(a[l]<=pivot&&l<=high)
        {
            l=l+1;
        }
         while(a[r]>pivot&&r>=low)
         {
             r=r-1;
         }
         if(l<r)
         {
             swap(&a[l],&a[r]);
             l=l+1;
             r=r-1;
         }
         else
         {
             /*move pivot to its position*/
             swap(&a[l-1],&a[low]);
             return l-1;
         }
    }
}
