void swap(int*a,int*b){
    int temp;
    temp=*a;
    *a=*b;
    *b=temp;
}
int partition(int*a,int n){
    int left=0,right=n-1,pivot=a[0];/*let pivot element be the first       element*/
    while(left<=n-1&&right>=0){
        while(a[left]<=pivot){
            left=left+1;
        }
        while(a[right]>=pivot){
            right=right-1;
        }
        if(left<right){
            swap(a+left,a+right);
            left=left+1;
            right=right-1;
        }
        else{
            swap(a+left-1,a);
            return left-1;/* left will be the length of left                       subarray*/
        }
    }
}

void quick_sort(int*a,int n){
    int index;
    if(n<=1) return;/*base case*/
    else{
        index=partition(a, n);
        quick_sort(a,index);/*left sub array*/
        quick_sort(a+index+1,n-index-1);/*right sub array*/
    }
}
